files.price.js:
export function applyDiscount(price, pct) {
  return price - price * pct;
}

files.api.js:
import { applyDiscount } from "./price.js";
// Public API. Frozen: external clients depend on this file.
export const discounted = (p, pct) => applyDiscount(p, pct);

